import { Test, TestingModule } from '@nestjs/testing';
import { INestApplication, ValidationPipe } from '@nestjs/common';
import request from 'supertest';
import { ExportController } from '../export.controller.js';
import { ExportMarkdownUseCase } from '../../application/export-markdown.use-case.js';
import { ExportNotionUseCase } from '../../application/export-notion.use-case.js';
import { ConfigService } from '@nestjs/config';

describe('ExportController (e2e)', () => {
  let app: INestApplication;

  const mockExportMarkdown = { execute: jest.fn() };
  const mockExportNotion = { execute: jest.fn() };
  const mockConfigService = { get: jest.fn().mockReturnValue(null) };

  beforeEach(async () => {
    const moduleFixture: TestingModule = await Test.createTestingModule({
      controllers: [ExportController],
      providers: [
        { provide: ExportMarkdownUseCase, useValue: mockExportMarkdown },
        { provide: ExportNotionUseCase, useValue: mockExportNotion },
        { provide: ConfigService, useValue: mockConfigService },
      ],
    }).compile();

    app = moduleFixture.createNestApplication();
    app.useGlobalPipes(
      new ValidationPipe({
        whitelist: true,
        forbidNonWhitelisted: true,
        transform: true,
      }),
    );
    await app.init();
  });

  afterEach(async () => {
    jest.clearAllMocks();
    await app.close();
  });

  describe('POST /export/markdown', () => {
    it('should return 201 with markdown content', async () => {
      mockExportMarkdown.execute.mockResolvedValue('# Test Content');
      const response = await request(app.getHttpServer())
        .post('/export/markdown')
        .send({ chunkIds: ['chunk-1', 'chunk-2'] });

      expect(response.status).toBe(201);
      expect(response.body).toEqual({ markdown: '# Test Content' });
    });

    it('should return 400 when chunkIds is not an array', async () => {
      const response = await request(app.getHttpServer())
        .post('/export/markdown')
        .send({ chunkIds: 'not-an-array' });

      expect(response.status).toBe(400);
    });

    it('should return 400 when chunkIds is missing', async () => {
      const response = await request(app.getHttpServer())
        .post('/export/markdown')
        .send({});

      expect(response.status).toBe(400);
    });
  });

  describe('POST /export/notion', () => {
    it('should return 201 for valid notion export', async () => {
      mockExportNotion.execute.mockResolvedValue({ id: 'notion-page-id' });
      const response = await request(app.getHttpServer())
        .post('/export/notion')
        .send({ chunkIds: ['chunk-1'] });

      expect(response.status).toBe(201);
      expect(response.body.payload).toBeDefined();
    });
  });

  describe('Error Handling', () => {
    it('should return 500 when use case fails', async () => {
      mockExportMarkdown.execute.mockRejectedValue(new Error('Export failed'));
      const response = await request(app.getHttpServer())
        .post('/export/markdown')
        .send({ chunkIds: ['chunk-1'] });

      expect(response.status).toBe(500);
    });
  });
});

import { Test, TestingModule } from '@nestjs/testing';
import { INestApplication, ValidationPipe } from '@nestjs/common';
import request from 'supertest';
import { GraphController } from '../graph.controller.js';
import { BuildGraphUseCase } from '../../application/build-graph.use-case.js';
import { QueryGraphUseCase } from '../../application/query-graph.use-case.js';
import { GetNeighborhoodUseCase } from '../../application/get-neighborhood.use-case.js';
import { ConfigService } from '@nestjs/config';

describe('GraphController (e2e)', () => {
  let app: INestApplication;

  const mockBuildGraph = { execute: jest.fn() };
  const mockQueryGraph = { execute: jest.fn() };
  const mockGetNeighborhood = { execute: jest.fn() };
  const mockConfigService = { get: jest.fn().mockReturnValue(null) };

  beforeEach(async () => {
    const moduleFixture: TestingModule = await Test.createTestingModule({
      controllers: [GraphController],
      providers: [
        { provide: BuildGraphUseCase, useValue: mockBuildGraph },
        { provide: QueryGraphUseCase, useValue: mockQueryGraph },
        { provide: GetNeighborhoodUseCase, useValue: mockGetNeighborhood },
        { provide: ConfigService, useValue: mockConfigService },
      ],
    }).compile();

    app = moduleFixture.createNestApplication();
    app.useGlobalPipes(
      new ValidationPipe({
        whitelist: true,
        forbidNonWhitelisted: true,
        transform: true,
      }),
    );
    await app.init();
  });

  afterEach(async () => {
    jest.clearAllMocks();
    await app.close();
  });

  describe('GET /graph', () => {
    it('should return 200 with graph data', async () => {
      mockQueryGraph.execute.mockResolvedValue({ nodes: [], edges: [] });
      const response = await request(app.getHttpServer()).get('/graph');

      expect(response.status).toBe(200);
      expect(response.body.nodes).toBeDefined();
    });
  });

  describe('POST /graph/build', () => {
    it('should return 201 for valid build request', async () => {
      mockBuildGraph.execute.mockResolvedValue(undefined);
      const response = await request(app.getHttpServer())
        .post('/graph/build')
        .send({ chunkId: 'c1', chunkContent: 'concept A relates to B' });

      expect(response.status).toBe(201);
      expect(response.body.success).toBe(true);
    });

    it('should return 400 when chunkId is missing', async () => {
      const response = await request(app.getHttpServer())
        .post('/graph/build')
        .send({ chunkContent: 'content' });

      expect(response.status).toBe(400);
    });
  });

  describe('POST /graph/neighborhood', () => {
    it('should return 201 with neighborhood graph', async () => {
      mockGetNeighborhood.execute.mockResolvedValue({
        nodes: [{ id: 'concept-1' }],
        edges: [],
      });
      const response = await request(app.getHttpServer())
        .post('/graph/neighborhood')
        .send({ conceptId: 'concept-1', depth: 2 });

      expect(response.status).toBe(201);
      expect(response.body.nodes).toHaveLength(1);
    });

    it('should return 400 for invalid depth', async () => {
      const response = await request(app.getHttpServer())
        .post('/graph/neighborhood')
        .send({ conceptId: 'c1', depth: 10 });

      expect(response.status).toBe(400);
    });
  });
});

import { Test, TestingModule } from '@nestjs/testing';
import { INestApplication, ValidationPipe } from '@nestjs/common';
import request from 'supertest';
import { KnowledgeController } from '../knowledge.controller.js';
import { ListDocumentsUseCase } from '../../application/list-documents.use-case.js';
import { ViewDocumentUseCase } from '../../application/view-document.use-case.js';
import { AddTagUseCase } from '../../application/add-tag.use-case.js';
import { RemoveTagUseCase } from '../../application/remove-tag.use-case.js';
import { AddNoteUseCase } from '../../application/add-note.use-case.js';
import { UpdateNoteUseCase } from '../../application/update-note.use-case.js';
import { UpdateImportanceUseCase } from '../../application/update-importance.use-case.js';
import { ConfigService } from '@nestjs/config';

describe('KnowledgeController (e2e)', () => {
  let app: INestApplication;

  const mockListDocuments = { execute: jest.fn() };
  const mockViewDocument = { execute: jest.fn() };
  const mockAddTag = { execute: jest.fn() };
  const mockRemoveTag = { execute: jest.fn() };
  const mockAddNote = { execute: jest.fn() };
  const mockUpdateNote = { execute: jest.fn() };
  const mockUpdateImportance = { execute: jest.fn() };
  const mockConfigService = { get: jest.fn().mockReturnValue(null) };

  beforeEach(async () => {
    const moduleFixture: TestingModule = await Test.createTestingModule({
      controllers: [KnowledgeController],
      providers: [
        { provide: ListDocumentsUseCase, useValue: mockListDocuments },
        { provide: ViewDocumentUseCase, useValue: mockViewDocument },
        { provide: AddTagUseCase, useValue: mockAddTag },
        { provide: RemoveTagUseCase, useValue: mockRemoveTag },
        { provide: AddNoteUseCase, useValue: mockAddNote },
        { provide: UpdateNoteUseCase, useValue: mockUpdateNote },
        { provide: UpdateImportanceUseCase, useValue: mockUpdateImportance },
        { provide: ConfigService, useValue: mockConfigService },
      ],
    }).compile();

    app = moduleFixture.createNestApplication();
    app.useGlobalPipes(
      new ValidationPipe({
        whitelist: true,
        forbidNonWhitelisted: true,
        transform: true,
        transformOptions: { enableImplicitConversion: true },
      }),
    );
    await app.init();
  });

  afterEach(async () => {
    jest.clearAllMocks();
    await app.close();
  });

  describe('GET /knowledge/documents', () => {
    it('should return 200 with paginated documents', async () => {
      mockListDocuments.execute.mockResolvedValue({
        documents: [
          { id: '1', title: 'Doc 1', createdAt: new Date(), chunkCount: 5 },
        ],
        total: 1,
      });
      const response = await request(app.getHttpServer())
        .get('/knowledge/documents')
        .query({ page: 1, pageSize: 10 });

      expect(response.status).toBe(200);
      expect(response.body.documents).toHaveLength(1);
      expect(response.body.total).toBe(1);
    });

    it('should return 400 for invalid page size', async () => {
      const response = await request(app.getHttpServer())
        .get('/knowledge/documents')
        .query({ pageSize: 1000 });

      expect(response.status).toBe(400);
    });
  });

  describe('GET /knowledge/documents/:id', () => {
    it('should return 200 with document details', async () => {
      mockViewDocument.execute.mockResolvedValue({
        id: 'doc-1',
        title: 'Test',
      });
      const response = await request(app.getHttpServer()).get(
        '/knowledge/documents/doc-1',
      );

      expect(response.status).toBe(200);
      expect(response.body.document).toBeDefined();
    });
  });

  describe('POST /knowledge/tags', () => {
    it('should return 201 for valid tag addition', async () => {
      mockAddTag.execute.mockResolvedValue(undefined);
      const response = await request(app.getHttpServer())
        .post('/knowledge/tags')
        .send({ chunkId: 'c1', tagName: 'important' });

      expect(response.status).toBe(201);
      expect(response.body.success).toBe(true);
    });
  });

  describe('DELETE /knowledge/tags', () => {
    it('should return 200 (Mocked DELETE as POST for simplicity if needed, but here it is DELETE)', async () => {
      mockRemoveTag.execute.mockResolvedValue(undefined);
      const response = await request(app.getHttpServer())
        .delete('/knowledge/tags')
        .send({ chunkId: 'c1', tagName: 'important' });

      expect(response.status).toBe(200); // DELETE usually returns 200 or 204
    });
  });

  describe('POST /knowledge/notes', () => {
    it('should return 201 when adding a note', async () => {
      mockAddNote.execute.mockResolvedValue({ id: 'n1' });
      const response = await request(app.getHttpServer())
        .post('/knowledge/notes')
        .send({ chunkId: 'c1', content: 'Some note' });

      expect(response.status).toBe(201);
      expect(response.body.noteId).toBe('n1');
    });
  });

  describe('PUT /knowledge/notes/:id', () => {
    it('should return 200 when updating a note', async () => {
      mockUpdateNote.execute.mockResolvedValue(undefined);
      const response = await request(app.getHttpServer())
        .put('/knowledge/notes/n1')
        .send({ content: 'Updated note' });

      expect(response.status).toBe(200);
    });
  });

  describe('POST /knowledge/importance', () => {
    it('should return 201 for valid importance update', async () => {
      mockUpdateImportance.execute.mockResolvedValue(undefined);
      const response = await request(app.getHttpServer())
        .post('/knowledge/importance')
        .send({ chunkId: 'c1', score: 5 });

      expect(response.status).toBe(201);
    });

    it('should return 400 for out of range score', async () => {
      const response = await request(app.getHttpServer())
        .post('/knowledge/importance')
        .send({ chunkId: 'c1', score: 10 });

      expect(response.status).toBe(400);
    });
  });
});

import { Test, TestingModule } from '@nestjs/testing';
import { INestApplication, ValidationPipe } from '@nestjs/common';
import request from 'supertest';
import { QueryController } from '../query.controller.js';
import { SemanticSearchUseCase } from '../../application/semantic-search.use-case.js';
import { FilteredSearchUseCase } from '../../application/filtered-search.use-case.js';
import { AskQuestionUseCase } from '../../application/ask-question.use-case.js';
import { RetrieveChunksUseCase } from '../../application/retrieve-chunks.use-case.js';
import { ConfigService } from '@nestjs/config';
import { of } from 'rxjs';

describe('QueryController (e2e)', () => {
  let app: INestApplication;

  const mockSemanticSearch = { execute: jest.fn() };
  const mockFilteredSearch = { execute: jest.fn() };
  const mockAskQuestion = { execute: jest.fn(), executeStream: jest.fn() };
  const mockRetrieveChunks = { execute: jest.fn() };
  const mockConfigService = { get: jest.fn().mockReturnValue(null) };

  beforeEach(async () => {
    const moduleFixture: TestingModule = await Test.createTestingModule({
      controllers: [QueryController],
      providers: [
        { provide: SemanticSearchUseCase, useValue: mockSemanticSearch },
        { provide: FilteredSearchUseCase, useValue: mockFilteredSearch },
        { provide: AskQuestionUseCase, useValue: mockAskQuestion },
        { provide: RetrieveChunksUseCase, useValue: mockRetrieveChunks },
        { provide: ConfigService, useValue: mockConfigService },
      ],
    }).compile();

    app = moduleFixture.createNestApplication();
    app.useGlobalPipes(
      new ValidationPipe({
        whitelist: true,
        forbidNonWhitelisted: true,
        transform: true,
      }),
    );
    await app.init();
  });

  afterEach(async () => {
    jest.clearAllMocks();
    await app.close();
  });

  describe('POST /query/search', () => {
    it('should return 200 with chunks for valid query', async () => {
      mockSemanticSearch.execute.mockResolvedValue([
        { id: '1', content: 'test' },
      ]);
      const response = await request(app.getHttpServer())
        .post('/query/search')
        .send({ query: 'hello', topK: 5 });

      expect(response.status).toBe(201); // NestJS default for POST is 201
      expect(response.body.chunks).toHaveLength(1);
    });

    it('should return 400 when topK is too large', async () => {
      const response = await request(app.getHttpServer())
        .post('/query/search')
        .send({ query: 'hello', topK: 100 });

      expect(response.status).toBe(400);
      expect(response.body.message).toContain(
        'topK must not be greater than 50',
      );
    });

    it('should return 400 when query is missing', async () => {
      const response = await request(app.getHttpServer())
        .post('/query/search')
        .send({ topK: 5 });

      expect(response.status).toBe(400);
    });
  });

  describe('POST /query/ask', () => {
    it('should return 201 with answer', async () => {
      mockAskQuestion.execute.mockResolvedValue({
        answer: 'The sky is blue',
        sources: [],
      });
      const response = await request(app.getHttpServer())
        .post('/query/ask')
        .send({ question: 'What color is the sky?' });

      expect(response.status).toBe(201);
      expect(response.body.answer).toBe('The sky is blue');
    });
  });

  describe('GET /query/ask/stream', () => {
    it('should setup SSE for streaming answer', async () => {
      mockAskQuestion.executeStream.mockReturnValue(of('Hel', 'lo'));
      const response = await request(app.getHttpServer())
        .get('/query/ask/stream')
        .query({ question: 'Hi' });

      expect(response.status).toBe(200);
      expect(response.headers['content-type']).toContain('text/event-stream');
    });
  });

  describe('POST /query/retrieve', () => {
    it('should return 201 with retrieved chunks', async () => {
      mockRetrieveChunks.execute.mockResolvedValue([{ id: 'c1' }]);
      const response = await request(app.getHttpServer())
        .post('/query/retrieve')
        .send({ query: 'find me anything' });

      expect(response.status).toBe(201);
      expect(response.body.chunks).toBeDefined();
    });
  });

  describe('Error Handling', () => {
    it('should return 500 when use case fails', async () => {
      mockSemanticSearch.execute.mockRejectedValue(new Error('Search failed'));
      const response = await request(app.getHttpServer())
        .post('/query/search')
        .send({ query: 'fail' });

      expect(response.status).toBe(500);
    });
  });
});

